+                pre.combiner[node_id].get_Appending_cur_idx() as int,
+                pre.buffer_size));
+        }
+    };
     assert forall |k| start <= k <= cur
         ==> log_entry_is_alive(pre.alive_bits, k, pre.buffer_size) by { }
     assert(pre.contents.contains_key(cur as int));
 }

